// keccak-f[1600] on a bit-interleaved state (even word, odd word per lane), in place.
// some of this code was generated by a python script instead of writing it by hand.
// this way the lane offsets, rotation amounts and stack offsets are computed and not typed in.
// this avoids human errors which would be difficult to trace, like wrong addresses or registers
// also the code repeates itself alot so some sections are simple to generate with fstrings in python
//
// a lane (x,y) is at state + 8*(x + 5*y). its even word is at +0 and its odd word is at +4.
// lane 1,0 means x=1, y=0.
//
// instead of doing theta, rho, pi and chi as four separate passes over the state in memory,
// we compute the column parities once, and then we build the new state one row at a time.
// each new row loads the lanes that pi moves into it, xors the theta mixing terms,
// rotates (rho), does chi and stores the result in the other buffer.
// --------------------------------------------------------------------------------------------
// AI DISCLAIMER: i used claude to generate the start of the file (mostly only the boilerplate)
// and the c functions that do bit interleaving. other than that:
// I wrote the entire assembly function by hand (with some help of python scripts)
// one of the python scripts was written by claude, and two by me. 
// i tried to comment as much as possible because its easier (for me) to keep track of what
// goes on here.
// ANYWAY, after I finished writing everything I tested the script and found that It had poor
// performance on the board. I got some help from claude with optimization (like the second 
// state that swaps every round).
// also i used ai to proofread the assembly and correct/add comments and it caught some
// mistakes i made.
// sorry for the long disclaimer
// --------------------------------------------------------------------------------------------
.syntax unified
.thumb
.text

.align 2
// access with:
// ldr rX, [r2], #4
// this loads word at r2 to rX and increments r2 by 4 bytes (next constant, accounting for bit interleaving)
round_constants:
    .word 0x00000001
    .word 0x00000000
    .word 0x00000000
    .word 0x00000089
    .word 0x00000000
    .word 0x8000008b
    .word 0x00000000
    .word 0x80008080
    .word 0x00000001
    .word 0x0000008b
    .word 0x00000001
    .word 0x00008000
    .word 0x00000001
    .word 0x80008088
    .word 0x00000001
    .word 0x80000082
    .word 0x00000000
    .word 0x0000000b
    .word 0x00000000
    .word 0x0000000a
    .word 0x00000001
    .word 0x00008082
    .word 0x00000000
    .word 0x00008003
    .word 0x00000001
    .word 0x0000808b
    .word 0x00000001
    .word 0x8000000b
    .word 0x00000001
    .word 0x8000008a
    .word 0x00000001
    .word 0x80000081
    .word 0x00000000
    .word 0x80000081
    .word 0x00000000
    .word 0x80000008
    .word 0x00000000
    .word 0x00000083
    .word 0x00000000
    .word 0x80008003
    .word 0x00000001
    .word 0x80008088
    .word 0x00000000
    .word 0x80000088
    .word 0x00000001
    .word 0x00008000
    .word 0x00000000
    .word 0x80008082

.global keccakf1600
.align 2
.thumb_func
.type keccakf1600, %function
// void keccakf1600(uint32_t *state);
keccakf1600:

    push {r4-r11, lr} // preserve callee saved registers
    sub sp, sp, #252 // second state buffer at sp+0, mixing terms at sp+200
    mov r1, sp
    adr r2, round_constants
    str r2, [sp, #240]
    add r3, r2, #192 // 24 rounds * 2 words * 4 bytes
    str r3, [sp, #244]

// r0 - source state (the state pointer in the first round)
// r1 - destination state (the stack buffer in the first round)
// r2 - round constants pointer
// r3-r12, lr - working regs

.align 2
round_start:
        // we first compute the column parities. even parities in r3-r7 and odd parities in r8-r12
        // first row
        ldr r3, [r0, #0] // lane 0,0 (even)
        ldr r4, [r0, #8] // lane 1,0 (even)
        ldr r5, [r0, #16] // lane 2,0 (even)
        ldr r6, [r0, #24] // lane 3,0 (even)
        ldr r7, [r0, #32] // lane 4,0 (even)
        ldr r8, [r0, #4] // lane 0,0 (odd)
        ldr r9, [r0, #12] // lane 1,0 (odd)
        ldr r10, [r0, #20] // lane 2,0 (odd)
        ldr r11, [r0, #28] // lane 3,0 (odd)
        ldr r12, [r0, #36] // lane 4,0 (odd)

        // now we xor the other 4 rows into the parities
        // we use r2 and lr to load, and alternate between them to minimize wait cycles during memory calls
        ldr r2, [r0, #40] // lane 0,1 (even)
        ldr lr, [r0, #48] // lane 1,1 (even)
        eor r3, r3, r2
        ldr r2, [r0, #56] // lane 2,1 (even)
        eor r4, r4, lr
        ldr lr, [r0, #64] // lane 3,1 (even)
        eor r5, r5, r2
        ldr r2, [r0, #72] // lane 4,1 (even)
        eor r6, r6, lr
        ldr lr, [r0, #44] // lane 0,1 (odd)
        eor r7, r7, r2
        ldr r2, [r0, #52] // lane 1,1 (odd)
        eor r8, r8, lr
        ldr lr, [r0, #60] // lane 2,1 (odd)
        eor r9, r9, r2
        ldr r2, [r0, #68] // lane 3,1 (odd)
        eor r10, r10, lr
        ldr lr, [r0, #76] // lane 4,1 (odd)
        eor r11, r11, r2
        ldr r2, [r0, #80] // lane 0,2 (even)
        eor r12, r12, lr
        ldr lr, [r0, #88] // lane 1,2 (even)
        eor r3, r3, r2
        ldr r2, [r0, #96] // lane 2,2 (even)
        eor r4, r4, lr
        ldr lr, [r0, #104] // lane 3,2 (even)
        eor r5, r5, r2
        ldr r2, [r0, #112] // lane 4,2 (even)
        eor r6, r6, lr
        ldr lr, [r0, #84] // lane 0,2 (odd)
        eor r7, r7, r2
        ldr r2, [r0, #92] // lane 1,2 (odd)
        eor r8, r8, lr
        ldr lr, [r0, #100] // lane 2,2 (odd)
        eor r9, r9, r2
        ldr r2, [r0, #108] // lane 3,2 (odd)
        eor r10, r10, lr
        ldr lr, [r0, #116] // lane 4,2 (odd)
        eor r11, r11, r2
        ldr r2, [r0, #120] // lane 0,3 (even)
        eor r12, r12, lr
        ldr lr, [r0, #128] // lane 1,3 (even)
        eor r3, r3, r2
        ldr r2, [r0, #136] // lane 2,3 (even)
        eor r4, r4, lr
        ldr lr, [r0, #144] // lane 3,3 (even)
        eor r5, r5, r2
        ldr r2, [r0, #152] // lane 4,3 (even)
        eor r6, r6, lr
        ldr lr, [r0, #124] // lane 0,3 (odd)
        eor r7, r7, r2
        ldr r2, [r0, #132] // lane 1,3 (odd)
        eor r8, r8, lr
        ldr lr, [r0, #140] // lane 2,3 (odd)
        eor r9, r9, r2
        ldr r2, [r0, #148] // lane 3,3 (odd)
        eor r10, r10, lr
        ldr lr, [r0, #156] // lane 4,3 (odd)
        eor r11, r11, r2
        ldr r2, [r0, #160] // lane 0,4 (even)
        eor r12, r12, lr
        ldr lr, [r0, #168] // lane 1,4 (even)
        eor r3, r3, r2
        ldr r2, [r0, #176] // lane 2,4 (even)
        eor r4, r4, lr
        ldr lr, [r0, #184] // lane 3,4 (even)
        eor r5, r5, r2
        ldr r2, [r0, #192] // lane 4,4 (even)
        eor r6, r6, lr
        ldr lr, [r0, #164] // lane 0,4 (odd)
        eor r7, r7, r2
        ldr r2, [r0, #172] // lane 1,4 (odd)
        eor r8, r8, lr
        ldr lr, [r0, #180] // lane 2,4 (odd)
        eor r9, r9, r2
        ldr r2, [r0, #188] // lane 3,4 (odd)
        eor r10, r10, lr
        ldr lr, [r0, #196] // lane 4,4 (odd)
        eor r11, r11, r2
        eor r12, r12, lr

        // now that were done computing the parities
        // we can calculate
        // the mixing terms
        // even mixing term of column x = even parity of column x-1 xor (odd parity of column x+1 rotated)
        // odd mixing term of column x = odd parity of column x-1 xor even parity of column x+1
        // we save the mixing terms on the stack
        eor r2, r7, r9, ror #31 // calculate even mixing term of column 0
        str r2, [sp, #200]
        eor lr, r12, r4 // calculate odd mixing term of column 0
        str lr, [sp, #220]
        eor r2, r3, r10, ror #31 // calculate even mixing term of column 1
        str r2, [sp, #204]
        eor lr, r8, r5 // calculate odd mixing term of column 1
        str lr, [sp, #224]
        eor r2, r4, r11, ror #31 // calculate even mixing term of column 2
        str r2, [sp, #208]
        eor lr, r9, r6 // calculate odd mixing term of column 2
        str lr, [sp, #228]
        eor r2, r5, r12, ror #31 // calculate even mixing term of column 3
        str r2, [sp, #212]
        eor lr, r10, r7 // calculate odd mixing term of column 3
        str lr, [sp, #232]
        eor r2, r6, r8, ror #31 // calculate even mixing term of column 4
        str r2, [sp, #216]
        eor lr, r11, r3 // calculate odd mixing term of column 4
        str lr, [sp, #236]

        ldr r2, [sp, #240] // round constant pointer

        // now we start xor'ing the mixing terms into the state, together with rho, pi and chi.
        // the new state is built one row at a time, and written to the destination buffer.
        // pi moves lane (x,y) to lane (y, 2x+3y), so the 5 lanes of new row Y come from
        // the lanes (x+3Y, x) for x = 0..4. because in the chi function, the even bits only interact with the
        // other even bits, we can execute it seperately, iteratively over all rows.
        // so we do the even bits of a row and then the odd bits of the same row.

        // row 0, even bits
        // lanes 0,0, 1,1, 2,2, 3,3, 4,4 are the new lanes 0,0 to 4,0
        // we load everything first to minimize wait cycles during memory calls
        ldr r3, [r0, #0] // lane 0,0 (even)
        ldr r4, [r0, #48] // lane 1,1 (even)
        ldr r5, [r0, #100] // lane 2,2 (odd)
        ldr r6, [r0, #148] // lane 3,3 (odd)
        ldr r7, [r0, #192] // lane 4,4 (even)
        ldr r8, [sp, #200] // even mixing term of column 0
        ldr r9, [sp, #204] // even mixing term of column 1
        ldr r10, [sp, #228] // odd mixing term of column 2
        ldr r11, [sp, #232] // odd mixing term of column 3
        ldr r12, [sp, #216] // even mixing term of column 4
        ldr lr, [r2], #4 // round constant (even)
        eor r3, r3, r8 // xor the mixing term into lane 0,0
        eor r4, r4, r9 // xor the mixing term into lane 1,1
        eor r5, r5, r10 // xor the mixing term into lane 2,2
        eor r6, r6, r11 // xor the mixing term into lane 3,3
        eor r7, r7, r12 // xor the mixing term into lane 4,4
        // lane 0,0 rotates by 0, this word doesnt move
        ror r4, r4, #10 // rotate lane 1,1 by 44
        ror r5, r5, #10 // rotate lane 2,2 by 43
        ror r6, r6, #21 // rotate lane 3,3 by 21
        ror r7, r7, #25 // rotate lane 4,4 by 14
        bic r8, r5, r4 // r8 = r5 and (not r4)
        eor r8, r8, r3 // r8 = r8 xor r3
        // iota step is just xoring the first lane with our current constant:
        eor r8, r8, lr
        str r8, [r1, #0] // new lane 0,0 (even)
        bic r9, r6, r5 // r9 = r6 and (not r5)
        eor r9, r9, r4 // r9 = r9 xor r4
        str r9, [r1, #8] // new lane 1,0 (even)
        bic r10, r7, r6 // r10 = r7 and (not r6)
        eor r10, r10, r5 // r10 = r10 xor r5
        str r10, [r1, #16] // new lane 2,0 (even)
        bic r11, r3, r7 // r11 = r3 and (not r7)
        eor r11, r11, r6 // r11 = r11 xor r6
        str r11, [r1, #24] // new lane 3,0 (even)
        bic r12, r4, r3 // r12 = r4 and (not r3)
        eor r12, r12, r7 // r12 = r12 xor r7
        str r12, [r1, #32] // new lane 4,0 (even)

        // row 0, odd bits
        // lanes 0,0, 1,1, 2,2, 3,3, 4,4 are the new lanes 0,0 to 4,0
        // we load everything first to minimize wait cycles during memory calls
        ldr r3, [r0, #4] // lane 0,0 (odd)
        ldr r4, [r0, #52] // lane 1,1 (odd)
        ldr r5, [r0, #96] // lane 2,2 (even)
        ldr r6, [r0, #144] // lane 3,3 (even)
        ldr r7, [r0, #196] // lane 4,4 (odd)
        ldr r8, [sp, #220] // odd mixing term of column 0
        ldr r9, [sp, #224] // odd mixing term of column 1
        ldr r10, [sp, #208] // even mixing term of column 2
        ldr r11, [sp, #212] // even mixing term of column 3
        ldr r12, [sp, #236] // odd mixing term of column 4
        ldr lr, [r2], #4 // round constant (odd)
        eor r3, r3, r8 // xor the mixing term into lane 0,0
        eor r4, r4, r9 // xor the mixing term into lane 1,1
        eor r5, r5, r10 // xor the mixing term into lane 2,2
        eor r6, r6, r11 // xor the mixing term into lane 3,3
        eor r7, r7, r12 // xor the mixing term into lane 4,4
        // lane 0,0 rotates by 0, this word doesnt move
        ror r4, r4, #10 // rotate lane 1,1 by 44
        ror r5, r5, #11 // rotate lane 2,2 by 43
        ror r6, r6, #22 // rotate lane 3,3 by 21
        ror r7, r7, #25 // rotate lane 4,4 by 14
        bic r8, r5, r4 // r8 = r5 and (not r4)
        eor r8, r8, r3 // r8 = r8 xor r3
        // iota step is just xoring the first lane with our current constant:
        eor r8, r8, lr
        str r8, [r1, #4] // new lane 0,0 (odd)
        bic r9, r6, r5 // r9 = r6 and (not r5)
        eor r9, r9, r4 // r9 = r9 xor r4
        str r9, [r1, #12] // new lane 1,0 (odd)
        bic r10, r7, r6 // r10 = r7 and (not r6)
        eor r10, r10, r5 // r10 = r10 xor r5
        str r10, [r1, #20] // new lane 2,0 (odd)
        bic r11, r3, r7 // r11 = r3 and (not r7)
        eor r11, r11, r6 // r11 = r11 xor r6
        str r11, [r1, #28] // new lane 3,0 (odd)
        bic r12, r4, r3 // r12 = r4 and (not r3)
        eor r12, r12, r7 // r12 = r12 xor r7
        str r12, [r1, #36] // new lane 4,0 (odd)

        // row 1, even bits
        // lanes 3,0, 4,1, 0,2, 1,3, 2,4 are the new lanes 0,1 to 4,1
        // we load everything first to minimize wait cycles during memory calls
        ldr r3, [r0, #24] // lane 3,0 (even)
        ldr r4, [r0, #72] // lane 4,1 (even)
        ldr r5, [r0, #84] // lane 0,2 (odd)
        ldr r6, [r0, #132] // lane 1,3 (odd)
        ldr r7, [r0, #180] // lane 2,4 (odd)
        ldr r8, [sp, #212] // even mixing term of column 3
        ldr r9, [sp, #216] // even mixing term of column 4
        ldr r10, [sp, #220] // odd mixing term of column 0
        ldr r11, [sp, #224] // odd mixing term of column 1
        ldr r12, [sp, #228] // odd mixing term of column 2
        eor r3, r3, r8 // xor the mixing term into lane 3,0
        eor r4, r4, r9 // xor the mixing term into lane 4,1
        eor r5, r5, r10 // xor the mixing term into lane 0,2
        eor r6, r6, r11 // xor the mixing term into lane 1,3
        eor r7, r7, r12 // xor the mixing term into lane 2,4
        ror r3, r3, #18 // rotate lane 3,0 by 28
        ror r4, r4, #22 // rotate lane 4,1 by 20
        ror r5, r5, #30 // rotate lane 0,2 by 3
        ror r6, r6, #9 // rotate lane 1,3 by 45
        ror r7, r7, #1 // rotate lane 2,4 by 61
        bic r8, r5, r4 // r8 = r5 and (not r4)
        eor r8, r8, r3 // r8 = r8 xor r3
        str r8, [r1, #40] // new lane 0,1 (even)
        bic r9, r6, r5 // r9 = r6 and (not r5)
        eor r9, r9, r4 // r9 = r9 xor r4
        str r9, [r1, #48] // new lane 1,1 (even)
        bic r10, r7, r6 // r10 = r7 and (not r6)
        eor r10, r10, r5 // r10 = r10 xor r5
        str r10, [r1, #56] // new lane 2,1 (even)
        bic r11, r3, r7 // r11 = r3 and (not r7)
        eor r11, r11, r6 // r11 = r11 xor r6
        str r11, [r1, #64] // new lane 3,1 (even)
        bic r12, r4, r3 // r12 = r4 and (not r3)
        eor r12, r12, r7 // r12 = r12 xor r7
        str r12, [r1, #72] // new lane 4,1 (even)

        // row 1, odd bits
        // lanes 3,0, 4,1, 0,2, 1,3, 2,4 are the new lanes 0,1 to 4,1
        // we load everything first to minimize wait cycles during memory calls
        ldr r3, [r0, #28] // lane 3,0 (odd)
        ldr r4, [r0, #76] // lane 4,1 (odd)
        ldr r5, [r0, #80] // lane 0,2 (even)
        ldr r6, [r0, #128] // lane 1,3 (even)
        ldr r7, [r0, #176] // lane 2,4 (even)
        ldr r8, [sp, #232] // odd mixing term of column 3
        ldr r9, [sp, #236] // odd mixing term of column 4
        ldr r10, [sp, #200] // even mixing term of column 0
        ldr r11, [sp, #204] // even mixing term of column 1
        ldr r12, [sp, #208] // even mixing term of column 2
        eor r3, r3, r8 // xor the mixing term into lane 3,0
        eor r4, r4, r9 // xor the mixing term into lane 4,1
        eor r5, r5, r10 // xor the mixing term into lane 0,2
        eor r6, r6, r11 // xor the mixing term into lane 1,3
        eor r7, r7, r12 // xor the mixing term into lane 2,4
        ror r3, r3, #18 // rotate lane 3,0 by 28
        ror r4, r4, #22 // rotate lane 4,1 by 20
        ror r5, r5, #31 // rotate lane 0,2 by 3
        ror r6, r6, #10 // rotate lane 1,3 by 45
        ror r7, r7, #2 // rotate lane 2,4 by 61
        bic r8, r5, r4 // r8 = r5 and (not r4)
        eor r8, r8, r3 // r8 = r8 xor r3
        str r8, [r1, #44] // new lane 0,1 (odd)
        bic r9, r6, r5 // r9 = r6 and (not r5)
        eor r9, r9, r4 // r9 = r9 xor r4
        str r9, [r1, #52] // new lane 1,1 (odd)
        bic r10, r7, r6 // r10 = r7 and (not r6)
        eor r10, r10, r5 // r10 = r10 xor r5
        str r10, [r1, #60] // new lane 2,1 (odd)
        bic r11, r3, r7 // r11 = r3 and (not r7)
        eor r11, r11, r6 // r11 = r11 xor r6
        str r11, [r1, #68] // new lane 3,1 (odd)
        bic r12, r4, r3 // r12 = r4 and (not r3)
        eor r12, r12, r7 // r12 = r12 xor r7
        str r12, [r1, #76] // new lane 4,1 (odd)

        // row 2, even bits
        // lanes 1,0, 2,1, 3,2, 4,3, 0,4 are the new lanes 0,2 to 4,2
        // we load everything first to minimize wait cycles during memory calls
        ldr r3, [r0, #12] // lane 1,0 (odd)
        ldr r4, [r0, #56] // lane 2,1 (even)
        ldr r5, [r0, #108] // lane 3,2 (odd)
        ldr r6, [r0, #152] // lane 4,3 (even)
        ldr r7, [r0, #160] // lane 0,4 (even)
        ldr r8, [sp, #224] // odd mixing term of column 1
        ldr r9, [sp, #208] // even mixing term of column 2
        ldr r10, [sp, #232] // odd mixing term of column 3
        ldr r11, [sp, #216] // even mixing term of column 4
        ldr r12, [sp, #200] // even mixing term of column 0
        eor r3, r3, r8 // xor the mixing term into lane 1,0
        eor r4, r4, r9 // xor the mixing term into lane 2,1
        eor r5, r5, r10 // xor the mixing term into lane 3,2
        eor r6, r6, r11 // xor the mixing term into lane 4,3
        eor r7, r7, r12 // xor the mixing term into lane 0,4
        ror r3, r3, #31 // rotate lane 1,0 by 1
        ror r4, r4, #29 // rotate lane 2,1 by 6
        ror r5, r5, #19 // rotate lane 3,2 by 25
        ror r6, r6, #28 // rotate lane 4,3 by 8
        ror r7, r7, #23 // rotate lane 0,4 by 18
        bic r8, r5, r4 // r8 = r5 and (not r4)
        eor r8, r8, r3 // r8 = r8 xor r3
        str r8, [r1, #80] // new lane 0,2 (even)
        bic r9, r6, r5 // r9 = r6 and (not r5)
        eor r9, r9, r4 // r9 = r9 xor r4
        str r9, [r1, #88] // new lane 1,2 (even)
        bic r10, r7, r6 // r10 = r7 and (not r6)
        eor r10, r10, r5 // r10 = r10 xor r5
        str r10, [r1, #96] // new lane 2,2 (even)
        bic r11, r3, r7 // r11 = r3 and (not r7)
        eor r11, r11, r6 // r11 = r11 xor r6
        str r11, [r1, #104] // new lane 3,2 (even)
        bic r12, r4, r3 // r12 = r4 and (not r3)
        eor r12, r12, r7 // r12 = r12 xor r7
        str r12, [r1, #112] // new lane 4,2 (even)

        // row 2, odd bits
        // lanes 1,0, 2,1, 3,2, 4,3, 0,4 are the new lanes 0,2 to 4,2
        // we load everything first to minimize wait cycles during memory calls
        ldr r3, [r0, #8] // lane 1,0 (even)
        ldr r4, [r0, #60] // lane 2,1 (odd)
        ldr r5, [r0, #104] // lane 3,2 (even)
        ldr r6, [r0, #156] // lane 4,3 (odd)
        ldr r7, [r0, #164] // lane 0,4 (odd)
        ldr r8, [sp, #204] // even mixing term of column 1
        ldr r9, [sp, #228] // odd mixing term of column 2
        ldr r10, [sp, #212] // even mixing term of column 3
        ldr r11, [sp, #236] // odd mixing term of column 4
        ldr r12, [sp, #220] // odd mixing term of column 0
        eor r3, r3, r8 // xor the mixing term into lane 1,0
        eor r4, r4, r9 // xor the mixing term into lane 2,1
        eor r5, r5, r10 // xor the mixing term into lane 3,2
        eor r6, r6, r11 // xor the mixing term into lane 4,3
        eor r7, r7, r12 // xor the mixing term into lane 0,4
        // lane 1,0 rotates by 1, this word doesnt move
        ror r4, r4, #29 // rotate lane 2,1 by 6
        ror r5, r5, #20 // rotate lane 3,2 by 25
        ror r6, r6, #28 // rotate lane 4,3 by 8
        ror r7, r7, #23 // rotate lane 0,4 by 18
        bic r8, r5, r4 // r8 = r5 and (not r4)
        eor r8, r8, r3 // r8 = r8 xor r3
        str r8, [r1, #84] // new lane 0,2 (odd)
        bic r9, r6, r5 // r9 = r6 and (not r5)
        eor r9, r9, r4 // r9 = r9 xor r4
        str r9, [r1, #92] // new lane 1,2 (odd)
        bic r10, r7, r6 // r10 = r7 and (not r6)
        eor r10, r10, r5 // r10 = r10 xor r5
        str r10, [r1, #100] // new lane 2,2 (odd)
        bic r11, r3, r7 // r11 = r3 and (not r7)
        eor r11, r11, r6 // r11 = r11 xor r6
        str r11, [r1, #108] // new lane 3,2 (odd)
